#!/bin/sh
# I697: Megatracker (.mgt) plays through `selecta-cli render` as a RENDER-kind replayer (libxmp). One reachability test
# through the product entry point; the sentinel is the `replayer=xmp` line of render (the engine picked the plugin and
# ran its adapter). Fixture: tests/m3/fixtures/xmp_test.mgt (generated by make_xmp_fixture.py, see xmp_test.mgt.SOURCE).
# Asserts: the plugin ran, the WAV is not silent (energy of the 16-bit samples), the rendered frame count equals the
# song length (64 rows x 6 ticks at 125 BPM = 7.68 s, +-1%; --seconds 20 is longer, so the song's own end stops the render).
# Then `plugins --formats xmp` lists the claimed formats.
# usage: xmp_decode.sh <selecta-cli> <mgt-file>
set -u
cli=$1
field() { printf '%s\n' "$1" | tr ' ' '\n' | sed -n "s/^$2=//p" | head -1; }
fail() { echo "FAIL: $*"; exit 1; }
rate=44100
want_frames=338688
rm -f fd_xmp.wav
out=$("$cli" render "$2" --output fd_xmp.wav --seconds 20 --rate "$rate" 2>/dev/null) || fail "render failed: $2"
[ "$(field "$out" replayer)" = "xmp" ] || fail "$2: replayer=$(field "$out" replayer), want xmp"
got=$(field "$out" rendered_frames)
awk -v g="$got" -v w=$want_frames 'BEGIN { d = g - w; if (d < 0) d = -d; exit !(d <= w * 0.01) }' ||
    fail "$2: rendered_frames=$got, want $want_frames +-1%"
e=$(od -An -v -t d2 -j 44 fd_xmp.wav | tr -s " " "\n" | awk '$1 != "" { s += $1 * $1 } END { printf "%d", s }')
[ "$e" -gt 1000000 ] || fail "$2: silent output (energy $e)"
fm=$("$cli" plugins --formats xmp 2>&1) || fail "plugins --formats xmp: $fm"
for id in liq mgt musx coc fuchs; do
    printf '%s\n' "$fm" | grep -q "^player $id\$" || fail "format $id not listed: $fm"
done
echo xmp_decode_ok
